#include <iostream>
#include <iterator>
#include <algorithm>
#include <functional>

template<typename T> T median(T a, T b, T c) {
  if (a < b) { if (b < c) return b; else if (a < c) return c; else return a; }
  else { if (a < c) return a; else if (b < c) return c; else return b; }
}

template<typename Order> struct non_strict_op : std::binary_function<typename Order::second_argument_type, typename Order::first_argument_type, bool> {
  non_strict_op(Order o): order(o) {}
  bool operator()(typename Order::second_argument_type x, typename Order::first_argument_type y) const { return !order(y, x); }
  Order order;
};

template<typename Order> non_strict_op<Order> non_strict(Order o) { return non_strict_op<Order>(o); }

template<typename RandomAccessIterator, typename Order>
void quicksort(RandomAccessIterator first, RandomAccessIterator last, Order order) {
  if (first != last && first+1 != last) {
    typedef typename std::iterator_traits<RandomAccessIterator>::value_type T;
    RandomAccessIterator mid = first + (last - first)/2;
    T pivot = median(*first, *mid, *(last-1));
    RandomAccessIterator s1 = std::partition(first, last, std::bind2nd(order, pivot));
    RandomAccessIterator s2 = std::partition(s1, last, std::bind2nd(non_strict(order), pivot));
    quicksort(first, s1, order);
    quicksort(s2, last, order);
  }
}

template<typename RandomAccessIterator>
void quicksort(RandomAccessIterator first, RandomAccessIterator last) {
  quicksort(first, last, std::less<typename std::iterator_traits<RandomAccessIterator>::value_type>());
}

int main() {
  int a[] = {35, 12, 8, 99, 21, 5};
  int n = sizeof(a)/sizeof(a[0]);
  quicksort(a, a+n);
  std::cout << "Sorted: ";
  for (int i=0;i<n;++i) std::cout << a[i] << " ";
  std::cout << std::endl;
  return 0;
}
